BEGIN TRANSACTION;
CREATE TABLE activities (id INTEGER PRIMARY KEY, name TEXT NOT NULL DEFAULT 'New activity', category TEXT DEFAULT 'Daily & Weekly', dungeon TEXT, mode TEXT, tier TEXT, enabled BOOLEAN DEFAULT 1, main_default BOOLEAN DEFAULT 1, alt_default BOOLEAN DEFAULT 0, scope TEXT DEFAULT 'unknown_global', cadence TEXT DEFAULT 'weekly', attempts_per_reset REAL, membership_bonus_attempts REAL DEFAULT 0, charges_per_day REAL, charge_cap REAL, reward_claims_per_attempt REAL DEFAULT 1, membership_extra_claims REAL DEFAULT 0, weekly_claim_limit REAL, duration_minutes REAL DEFAULT 10, odyle_per_claim REAL DEFAULT 0, kinah_cost REAL DEFAULT 0, ap_cost REAL DEFAULT 0, ticket_cost REAL DEFAULT 0, entry_item_level REAL, recommended_item_level REAL, consumes_abyss_time BOOLEAN DEFAULT 0, ap_cap_category TEXT DEFAULT 'none', forced_initial_claims REAL DEFAULT 0, guaranteed_reward_after_claims REAL, guaranteed_reward_value REAL, repeat_after_guarantee BOOLEAN DEFAULT 1, ruleset TEXT DEFAULT 'user_override', source_status TEXT DEFAULT 'unknown', sort_order INTEGER DEFAULT 0, notes TEXT DEFAULT '', charge_cap_membership REAL, recharge_amount REAL, recharge_hours REAL, recharge_amount_membership REAL, recharge_hours_membership REAL, reward_tier TEXT);
CREATE TABLE activity_rewards (id INTEGER PRIMARY KEY, activity_id INTEGER REFERENCES activities(id) ON DELETE CASCADE, pool TEXT DEFAULT '', currency_key TEXT REFERENCES currencies(key) ON DELETE CASCADE, amount REAL DEFAULT 0, draws REAL DEFAULT 1, chance REAL DEFAULT 100);
CREATE TABLE character_activity (character_id INTEGER REFERENCES characters(id) ON DELETE CASCADE, activity_id INTEGER REFERENCES activities(id) ON DELETE CASCADE, enabled BOOLEAN, planned_runs REAL, use_extra_claim BOOLEAN DEFAULT 1, milestone_claims_done REAL DEFAULT 0, PRIMARY KEY (character_id, activity_id));
CREATE TABLE characters (id INTEGER PRIMARY KEY, name TEXT NOT NULL DEFAULT 'New character', class TEXT DEFAULT 'Gladiator', faction TEXT DEFAULT 'Asmodian', server TEXT DEFAULT 'Server 1', is_main BOOLEAN DEFAULT 0, membership BOOLEAN DEFAULT 1, level INTEGER DEFAULT 1, item_level INTEGER DEFAULT 0, combat_power INTEGER, pvp_item_level INTEGER, pvp_combat_power INTEGER, pvp_power_metric REAL, active BOOLEAN DEFAULT 1, sort_order INTEGER DEFAULT 0, notes TEXT DEFAULT '');
CREATE TABLE currencies (key TEXT PRIMARY KEY, name TEXT, category TEXT DEFAULT 'material', tradable BOOLEAN DEFAULT 0, bound BOOLEAN DEFAULT 1, shared BOOLEAN DEFAULT 0, estimated_kinah_value REAL, weight REAL DEFAULT 0, sort_order INTEGER DEFAULT 0, notes TEXT DEFAULT '', gs_per_unit REAL DEFAULT 0);
CREATE TABLE feather_regions (id INTEGER PRIMARY KEY, faction TEXT, region TEXT, count REAL, collected REAL DEFAULT 0, notes TEXT DEFAULT '');
CREATE TABLE fill (key TEXT PRIMARY KEY, filled REAL DEFAULT 0, total REAL DEFAULT 0);
CREATE TABLE gear_slots (id INTEGER PRIMARY KEY, character_id INTEGER REFERENCES characters(id) ON DELETE CASCADE, profile TEXT DEFAULT 'pve', slot TEXT, priority_score REAL DEFAULT 0, enhancement_level INTEGER DEFAULT 0, target_level INTEGER DEFAULT 0, material_budget REAL DEFAULT 0, notes TEXT DEFAULT '');
CREATE TABLE leveling_blocks (id INTEGER PRIMARY KEY, character_id INTEGER REFERENCES characters(id) ON DELETE CASCADE, block_type TEXT, label TEXT, start_level INTEGER, end_level INTEGER, hours REAL, required BOOLEAN DEFAULT 1, critical BOOLEAN DEFAULT 1, schedule_order INTEGER DEFAULT 0, done BOOLEAN DEFAULT 0, notes TEXT DEFAULT '', session INTEGER, part_hours REAL);
CREATE TABLE leveling_templates (id INTEGER PRIMARY KEY, role TEXT, block_type TEXT, label TEXT, start_level INTEGER, end_level INTEGER, hours REAL, required BOOLEAN DEFAULT 1, critical BOOLEAN DEFAULT 1, priority INTEGER DEFAULT 1, checklist TEXT DEFAULT '', options TEXT DEFAULT '{}', UNIQUE(role, block_type));
Nearby Empyrean Traces / Feathers when efficient
Sealed Dungeons on the route
Strongholds on the route
Relevant nearby side/regional quests
Orange / Daevanion progression quests when appropriate
Reach the Krao Cave MSQ/Expedition breakpoint
Avoid unnecessary resource spending during the rush','{"collect_feathers": true, "sealed_dungeons": true, "strongholds": true, "side_quests": "minimal", "spend_odyle": false}');
Nightmare unlocks via the MSQ chain (no separate unlock block)','{}');
Sealed Dungeons
Strongholds
Side/regional quests
Permanent Daevanion/skill-point progression
Accessible enemy-faction/Rift exploration
Other one-time progression','{}');
Route-critical Sealed Dungeons
Reach Krao Cave
Do not repeat shared Feather progression done on Main
Do not claim low-value Odyle cubes during leveling','{"collect_feathers": true, "sealed_dungeons": true, "strongholds": true, "side_quests": "minimal", "spend_odyle": false}');
Activate character-specific accumulating systems (Odyle, Nightmare charges) ASAP','{}');
Skip server-shared progression already completed','{}');
CREATE TABLE monolith_levels (id INTEGER PRIMARY KEY, monolith TEXT, level INTEGER, feathers REAL, reward TEXT DEFAULT '');
CREATE TABLE odyle_sources (id INTEGER PRIMARY KEY, name TEXT, source_type TEXT DEFAULT 'shop', scope TEXT DEFAULT 'per_character', purchases REAL DEFAULT 0, odyle_each REAL DEFAULT 40, kinah_cost_each REAL DEFAULT 0, enabled BOOLEAN DEFAULT 1, membership_required BOOLEAN DEFAULT 0, ruleset TEXT DEFAULT 'kr_tw_reference', source_status TEXT DEFAULT 'provisional', notes TEXT DEFAULT '', odyle_cost_each REAL DEFAULT 0, pure_odyle_cost_each REAL DEFAULT 0, refined_odyle_cost_each REAL DEFAULT 0);
CREATE TABLE one_time (id INTEGER PRIMARY KEY, kind TEXT, faction TEXT, region TEXT, name TEXT, level REAL, done BOOLEAN DEFAULT 0, notes TEXT DEFAULT '');
CREATE TABLE pity (id INTEGER PRIMARY KEY, category TEXT DEFAULT 'Expedition', mode TEXT, dungeon TEXT, claims_needed REAL, reward TEXT DEFAULT '', repeats BOOLEAN DEFAULT 1, max_times REAL, notes TEXT DEFAULT '');
CREATE TABLE progress (key TEXT PRIMARY KEY, done BOOLEAN DEFAULT 0);
CREATE TABLE progression_items (id INTEGER PRIMARY KEY, system TEXT, faction TEXT DEFAULT 'own', name TEXT NOT NULL DEFAULT 'New item', region TEXT DEFAULT '', level_req INTEGER, count REAL DEFAULT 1, minutes_each REAL DEFAULT 0, scope TEXT DEFAULT 'per_character', enabled BOOLEAN DEFAULT 1, main_default BOOLEAN DEFAULT 1, alt_default BOOLEAN DEFAULT 1, ruleset TEXT DEFAULT 'user_override', source_status TEXT DEFAULT 'unknown', sort_order INTEGER DEFAULT 0, notes TEXT DEFAULT '', capacity REAL);
CREATE TABLE progression_rewards (id INTEGER PRIMARY KEY, item_id INTEGER REFERENCES progression_items(id) ON DELETE CASCADE, pool TEXT DEFAULT '', currency_key TEXT REFERENCES currencies(key) ON DELETE CASCADE, amount REAL DEFAULT 0, draws REAL DEFAULT 1, chance REAL DEFAULT 100);
CREATE TABLE rulesets (key TEXT PRIMARY KEY, label TEXT, color TEXT DEFAULT 'gray', description TEXT DEFAULT '');
CREATE TABLE session_items (id INTEGER PRIMARY KEY, session INTEGER, schedule_order REAL DEFAULT 0, character_id INTEGER REFERENCES characters(id) ON DELETE CASCADE, activity_id INTEGER REFERENCES activities(id) ON DELETE CASCADE, runs REAL DEFAULT 1, done BOOLEAN DEFAULT 0, notes TEXT DEFAULT '');
CREATE TABLE sessions (number INTEGER PRIMARY KEY, name TEXT, permanent BOOLEAN DEFAULT 0, times_per_week REAL DEFAULT 7, notes TEXT DEFAULT '');
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE sources (id INTEGER PRIMARY KEY, activity_id INTEGER REFERENCES activities(id) ON DELETE SET NULL, ruleset TEXT DEFAULT 'user_override', source_name TEXT, source_url TEXT, verified_date TEXT, status TEXT DEFAULT 'provisional', notes TEXT DEFAULT '');
CREATE TABLE weekly_log (week_start TEXT, character_id INTEGER REFERENCES characters(id) ON DELETE CASCADE, activity_id INTEGER REFERENCES activities(id) ON DELETE CASCADE, runs_done REAL DEFAULT 0, PRIMARY KEY (week_start, character_id, activity_id));
COMMIT;
